import { Component } from '@angular/core';

@Component({
  selector: 'app-product-page',
  imports: [ProductSummary, ProductSpecs, Reviews],
  template: `
    <app-product-summary />
    <!-- The server renders only the skeleton here, and the page
         shifts when the real reviews replace it in the browser -->
    @defer (on viewport) {
      <app-reviews />
    } @placeholder {
      <div class="reviews-skeleton"></div>
    }
    <!-- Static text, but its code ships and hydrates up front -->
    <app-product-specs />
  `,
})
export class ProductPage {}

import { Component } from '@angular/core';

@Component({
  selector: 'app-product-page',
  imports: [ProductSummary, ProductSpecs, Reviews],
  template: `
    <app-product-summary />
    <!-- Rendered on the server; code loads when it's scrolled to -->
    @defer (on viewport; hydrate on viewport) {
      <app-reviews />
    } @placeholder {
      <div class="reviews-skeleton"></div>
    }
    <!-- Stays static on the first load: its code isn't downloaded -->
    @defer (on idle; hydrate never) {
      <app-product-specs />
    } @placeholder {
      <div class="specs-skeleton"></div>
    }
  `,
})
export class ProductPage {}
